\coordinate (R) at (4.6,2.4);
\coordinate (S) at (1.0,2.4);
\draw (P) -- (Q);
\draw (S) -- (R);
\draw (P) -- (S);
\draw (Q) -- (R);
\node[below left] at (P) {$P$};
\node[below right] at (Q) {$Q$};
\node[above right] at (R) {$R$};
\node[above left] at (S) {$S$};
\draw[->] (1.5,0) -- (2.1,0);
\draw[->] (2.5,2.4) -- (3.1,2.4);
